package de.schaepi.puls180;
import android.content.*;import org.json.*;import java.net.*;import java.io.*;import java.security.*;import java.security.cert.*;import javax.net.ssl.*;import java.util.*;
public final class PcSync {
 private static boolean busy=false;
 public interface Result {void done(boolean changed,String message);}
 public static String validate(String code)throws Exception{code=code.trim();if(code.startsWith("BP1|"))code=code.substring(4);String[] a=code.trim().split("\\|");if(a.length!=3||!a[0].matches("[0-9.]{7,15}")||!a[1].matches("[a-f0-9]{64}")||!a[2].matches("[a-f0-9]{64}"))throw new Exception();InetAddress ip=InetAddress.getByName(a[0]);if(!ip.isSiteLocalAddress()||ip.getAddress().length!=4)throw new Exception();return String.join("|",a);}
 public static void run(Context ctx,JSONArray rows,Result callback){start(ctx,rows,callback,false);}
 public static void poll(Context ctx,JSONArray rows,Result callback){start(ctx,rows,callback,true);}
 private static synchronized void start(Context ctx,JSONArray rows,Result callback,boolean onlyIfRequested){if(busy){if(!onlyIfRequested)callback.done(false,"Abgleich läuft bereits. Bitte gleich erneut senden.");return;}if(!License.allowed(ctx)){if(!onlyIfRequested)callback.done(false,"PC-Abgleich benötigt eine Freischaltung.");return;}Context c=ctx.getApplicationContext();String code=c.getSharedPreferences("pcSync",0).getString("code","");if(code.isEmpty())return;busy=true;
 new Thread(()->{boolean changed=false;String message;HttpsURLConnection conn=null;try{
 String[] a=validate(code).split("\\|");SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,new TrustManager[]{new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] x,String auth)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[] x,String auth)throws CertificateException{try{if(x.length==0)throw new Exception();x[0].checkValidity();byte[] digest=MessageDigest.getInstance("SHA-256").digest(x[0].getEncoded());StringBuilder hex=new StringBuilder();for(byte b:digest)hex.append(String.format(Locale.ROOT,"%02x",b&255));if(!MessageDigest.isEqual(hex.toString().getBytes("US-ASCII"),a[1].getBytes("US-ASCII")))throw new Exception();}catch(Exception e){throw new CertificateException("PC-Zertifikat stimmt nicht",e);}}}},new SecureRandom());
 if(onlyIfRequested){conn=open(a,ssl,"sync-needed",2500,4000);byte[] probe={123,125};conn.setFixedLengthStreamingMode(probe.length);try(OutputStream out=conn.getOutputStream()){out.write(probe);}if(conn.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream answer=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] b=new byte[512];int n;while((n=in.read(b))!=-1){if(answer.size()+n>4096)throw new IOException();answer.write(b,0,n);}}boolean requested=new JSONObject(answer.toString("UTF-8")).optBoolean("requested",false);conn.disconnect();conn=null;if(!requested)return;} conn=open(a,ssl,"sync",7000,15000);byte[] payload=new JSONObject().put("readings",rows).put("device",android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL).put("profile",String.valueOf(UserProfile.activeSlot(c))).put("profileName",UserProfile.activeLabel(c)).toString().getBytes("UTF-8");conn.setFixedLengthStreamingMode(payload.length);if(!License.allowed(c))throw new IOException("Test abgelaufen");try(OutputStream out=conn.getOutputStream()){out.write(payload);}if(conn.getResponseCode()!=200)throw new IOException("PC hat Übertragung abgelehnt");ByteArrayOutputStream buffer=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(buffer.size()+n>4000000)throw new IOException();buffer.write(b,0,n);}}
 if(!License.allowed(c))throw new IOException("Test abgelaufen");JSONArray incoming=new JSONObject(buffer.toString("UTF-8")).getJSONArray("readings");try(DirectStore store=new DirectStore(c)){for(int i=0;i<incoming.length();i++){JSONObject r=incoming.getJSONObject(i);String id=UUID.fromString(r.getString("id")).toString();java.time.Instant t=java.time.Instant.parse(r.getString("measuredAt"));double sys=r.getDouble("systolic"),dia=r.getDouble("diastolic"),pulse=r.isNull("pulse")?Double.NaN:r.getDouble("pulse");if(!Double.isFinite(sys)||!Double.isFinite(dia)||sys<=dia||dia<=0||sys>400||dia>300||t.isAfter(java.time.Instant.now().plusSeconds(300)))throw new IOException();if(store.importPc(id,t,sys,dia,pulse)){c.getSharedPreferences("MainActivity",0).edit().putString("note:"+c.getPackageName()+":"+id,r.optString("note","")).commit();changed=true;}c.getSharedPreferences("pcSync",0).edit().putBoolean("pc:"+id,true).apply();}}
 message="Abgeglichen um "+java.time.LocalTime.now().format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"))+" · "+rows.length()+" Messungen an PC";
 }catch(Exception e){if(onlyIfRequested)return;message="PC nicht erreichbar oder Kopplung ungültig. PC starten, gleiches WLAN und Kopplung prüfen. Bitte Verbindung prüfen und erneut senden.";}finally{if(conn!=null)conn.disconnect();synchronized(PcSync.class){busy=false;}}
 c.getSharedPreferences("pcSync",0).edit().putString("status",message).apply();final boolean updated=changed;final String result=message;new android.os.Handler(android.os.Looper.getMainLooper()).post(()->callback.done(updated,result));},"PC-Abgleich").start();}
 private static HttpsURLConnection open(String[] a,SSLContext ssl,String path,int connectTimeout,int readTimeout)throws Exception{HttpsURLConnection conn=(HttpsURLConnection)new URL("https://"+a[0]+":18776/"+path).openConnection();conn.setSSLSocketFactory(ssl.getSocketFactory());conn.setHostnameVerifier((host,session)->host.equals(a[0]));conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(connectTimeout);conn.setReadTimeout(readTimeout);conn.setRequestMethod("POST");conn.setRequestProperty("Authorization","Bearer "+a[2]);conn.setRequestProperty("Content-Type","application/json");conn.setDoOutput(true);return conn;}
}


